#!/usr/bin/env bash
# DOC + MODE SOMBRE :
#   - blocs de code des pages de doc : coloration syntaxique (shiki) ; la ligne « // chemin (extrait) »
#     devient un en-tête au-dessus du bloc (chemin + précision, langage, bouton Copier) ;
#   - carrousel d'accueil en sombre : chevrons inversés (fond clair, flèche sombre), pastilles et
#     boutons Continu / Diapo / Pause lisibles ;
#   - textes « prose » (corps d'actualité, blocs de texte, documents) en blanc en mode sombre, et
#     autres gris foncés posés en dur ramenés aux couleurs du thème.
# Prérequis : apply-docs-domaine-formulaires.sh.
# Usage (racine du repo) : bash apply-docs-code-dark.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/mdx-components.tsx" 2>/dev/null | grep -qF "MdxCodeFence"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "## Choisir sa technique" "apps/web/content/docs/dev/interface/formulaires.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-domaine-formulaires.sh"; exit 1; }
MODIFIED=("apps/web/src/features/app-shell/HomeCarousel.tsx" "apps/web/src/mdx-components.tsx" "apps/web/src/styles/dark-legacy.css")
CREATED=("apps/web/src/features/docs/ui/MdxCodeFence.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "MdxCodeFence" "apps/web/src/mdx-components.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/ui"
